  cp "$RAW" "$ROOFED"
else
  $MCD roof "$RAW" --style flat-parapet --footprint 0,7,15,30 --y 17 --dry-run
  $MCD roof "$RAW" "$ROOFED" --style flat-parapet --footprint 0,7,15,30 --y 17
fi

mv "$ROOFED" build.nbt
echo "# wrote $(pwd)/build.nbt"
